def _extract_image_and_state(self, obs):
    return {
        "full_image": get_libero_image(obs),
        "wrist_image": get_libero_wrist_image(obs),
        "state": np.concatenate(
            [
                obs["robot0_eef_pos"],
                quat2axisangle(obs["robot0_eef_quat"]),
                obs["robot0_gripper_qpos"],
            ]
        ),
    }

def _wrap_obs(self, obs_list):
    images_and_states_list = []
    for obs in obs_list:
        images_and_states = self._extract_image_and_state(obs)
        images_and_states_list.append(images_and_states)

    images_and_states = to_tensor(
        list_of_dict_to_dict_of_list(images_and_states_list)
    )

    full_image_tensor = torch.stack(
        [value.clone() for value in images_and_states["full_image"]]
    )
    wrist_image_tensor = torch.stack(
        [value.clone() for value in images_and_states["wrist_image"]]
    )

    states = images_and_states["state"]

    obs = {
        "main_images": full_image_tensor,
        "wrist_images": wrist_image_tensor,
        "states": states,
        "task_descriptions": self.task_descriptions,
    }

def _step_env(self, action) -> None:
    """Execute one env action between cancellation checkpoints."""
    self._check_cancelled()
    obs, reward, terminated, truncated, _info = self.env.step(action)
    if self._flywheel is not None:
        self._flywheel.add_transition(action, obs, reward, terminated, truncated)
    self.set_obs(obs)
    if self._recording:
        self.record_frame(obs)
